import sys
# Линейная система над 4 неизвестными-байтами.
def check(s):
    if len(s) != 4:
        return False
    a, b, c, d = [ord(x) for x in s]
    return (a + b == 164) and (b + c == 167) and (c + d == 230) and (a - d == -3)
if __name__ == '__main__':
    print("OK" if len(sys.argv) > 1 and check(sys.argv[1]) else "NO")
